dashboard.definition:
{
 "title": "Firewall Overview",
 "description": "Volume, posture and collection health across the estate, on the accelerable data model. Three tabs: summary, collection health, geography and changes.",
 "visualizations": {
  "hdr": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## Windows Defender Firewall — Overview\nVolume, posture and collection health across every monitored host. Counters run on the `Windows_Firewall_Observability` data model — accelerate it to make this page instant.",
    "fontSize": "large",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "kpi_hosts": {
   "type": "splunk.singlevalue",
   "title": "Hosts reporting",
   "dataSources": {
    "primary": "ds_kpi_card"
   },
   "options": {
    "majorValue": "> primary | seriesByName('hosts') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#4fa3ff"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_total": {
   "type": "splunk.singlevalue",
   "title": "Connections logged",
   "dataSources": {
    "primary": "ds_kpi_counts"
   },
   "options": {
    "majorValue": "> primary | seriesByName('total') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#dbe0e6"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_allowed": {
   "type": "splunk.singlevalue",
   "title": "Allowed",
   "dataSources": {
    "primary": "ds_kpi_counts"
   },
   "options": {
    "majorValue": "> primary | seriesByName('allowed') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#2fb67c"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_blocked": {
   "type": "splunk.singlevalue",
   "title": "Blocked",
   "dataSources": {
    "primary": "ds_kpi_counts"
   },
   "options": {
    "majorValue": "> primary | seriesByName('blocked') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#e5484d"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_blocked_pct": {
   "type": "splunk.singlevalue",
   "title": "Blocked ratio",
   "dataSources": {
    "primary": "ds_kpi_counts"
   },
   "options": {
    "majorValue": "> primary | seriesByName('blocked_pct') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 1,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)",
    "unit": "%",
    "unitPosition": "after"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 5,
      "value": "#2fb67c"
     },
     {
      "from": 5,
      "to": 25,
      "value": "#f5a623"
     },
     {
      "from": 25,
      "value": "#e5484d"
     }
    ]
   },
   "description": "Share of denied connections. A sudden jump usually means a scan, a broken app or a new policy."
  },
  "kpi_critical": {
   "type": "splunk.singlevalue",
   "title": "High / critical changes",
   "dataSources": {
    "primary": "ds_kpi_changes"
   },
   "options": {
    "majorValue": "> primary | seriesByName('critical') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 1,
      "value": "#2fb67c"
     },
     {
      "from": 1,
      "to": 5,
      "value": "#f5a623"
     },
     {
      "from": 5,
      "value": "#e5484d"
     }
    ]
   }
  },
  "hdr_traffic": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Traffic",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_timechart": {
   "type": "splunk.area",
   "title": "Allowed vs blocked over time",
   "dataSources": {
    "primary": "ds_timechart"
   },
   "options": {
    "stackMode": "stacked",
    "seriesColors": [
     "#2fb67c",
     "#e5484d",
     "#8c9199"
    ],
    "legendDisplay": "bottom",
    "yAxisTitleText": "Connections",
    "xAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "viz_direction": {
   "type": "splunk.pie",
   "title": "Direction and outcome",
   "dataSources": {
    "primary": "ds_direction"
   },
   "options": {
    "showDonutHole": true,
    "seriesColors": [
     "#2fb67c",
     "#e5484d",
     "#4fa3ff",
     "#f5a623",
     "#a175ff",
     "#31c2c9",
     "#e05f9e",
     "#8c9199"
    ],
    "legendDisplay": "right",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_focus": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Where the noise comes from — click a row to open the dedicated view",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_top_blocked": {
   "type": "splunk.bar",
   "title": "Top 10 blocked services",
   "dataSources": {
    "primary": "ds_top_blocked"
   },
   "options": {
    "seriesColors": [
     "#e5484d"
    ],
    "legendDisplay": "off",
    "xAxisTitleText": "Denied connections",
    "yAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "viz_top_talkers": {
   "type": "splunk.table",
   "title": "Top 10 talkers",
   "dataSources": {
    "primary": "ds_top_talkers"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Opens the Host 360 view for the selected machine.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.host.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_fw_state": {
   "type": "splunk.table",
   "title": "Firewall state by host",
   "dataSources": {
    "primary": "ds_fw_state"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "columnFormat": {
     "state": {
      "rowBackgroundColors": "> table | seriesByName(\"state\") | matchValue(stateBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "stateBgConfig": [
     {
      "match": "enabled",
      "value": "#14301f"
     },
     {
      "match": "disabled",
      "value": "#4a1015"
     }
    ],
    "statusBgConfig": [
     {
      "match": "healthy",
      "value": "#14301f"
     },
     {
      "match": "delayed",
      "value": "#3a2c17"
     },
     {
      "match": "stale",
      "value": "#4a1015"
     }
    ]
   },
   "description": "Based on the last Enable/Disable event received per host.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.Computer.value$",
      "newTab": false
     }
    }
   ]
  },
  "hdr_trellis": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Blocked ratio, host by host\nOne gauge per machine. An outlier here is usually a scan target, a broken application or a policy that just changed.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_trellis": {
   "type": "splunk.singlevalue",
   "title": "",
   "dataSources": {
    "primary": "ds_trellis_hosts"
   },
   "options": {
    "majorValue": "> primary | seriesByName('blocked_pct') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 1,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)",
    "unit": "%",
    "unitPosition": "after",
    "splitByLayout": "trellis",
    "trellisSplitBy": "host",
    "trellisMinColumnWidth": 200,
    "trellisRowHeight": 150,
    "trellisPageCount": 12
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 5,
      "value": "#2fb67c"
     },
     {
      "from": 5,
      "to": 25,
      "value": "#f5a623"
     },
     {
      "from": 25,
      "value": "#e5484d"
     }
    ]
   }
  },
  "hdr_cov": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Collection health\nStart here when a dashboard looks empty. A host that stopped shipping data is not a quiet host.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "kpi_cov_hosts": {
   "type": "splunk.singlevalue",
   "title": "Hosts sending data",
   "dataSources": {
    "primary": "ds_coverage_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('hosts') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#4fa3ff"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_cov_healthy": {
   "type": "splunk.singlevalue",
   "title": "Healthy",
   "dataSources": {
    "primary": "ds_coverage_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('healthy') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#2fb67c"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_cov_delayed": {
   "type": "splunk.singlevalue",
   "title": "Delayed",
   "dataSources": {
    "primary": "ds_coverage_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('delayed') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 1,
      "value": "#2fb67c"
     },
     {
      "from": 1,
      "value": "#f5a623"
     }
    ]
   }
  },
  "kpi_cov_stale": {
   "type": "splunk.singlevalue",
   "title": "Stale",
   "dataSources": {
    "primary": "ds_coverage_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('stale') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 1,
      "value": "#2fb67c"
     },
     {
      "from": 1,
      "value": "#e5484d"
     }
    ]
   },
   "description": "No firewall traffic for more than 24 hours."
  },
  "kpi_cov_pct": {
   "type": "splunk.singlevalue",
   "title": "Coverage",
   "dataSources": {
    "primary": "ds_coverage_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('healthy_pct') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 1,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)",
    "unit": "%",
    "unitPosition": "after"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 80,
      "value": "#e5484d"
     },
     {
      "from": 80,
      "to": 95,
      "value": "#f5a623"
     },
     {
      "from": 95,
      "value": "#2fb67c"
     }
    ]
   }
  },
  "viz_volume_host": {
   "type": "splunk.line",
   "title": "Event volume per host",
   "dataSources": {
    "primary": "ds_volume_host"
   },
   "options": {
    "seriesColors": [
     "#2fb67c",
     "#e5484d",
     "#4fa3ff",
     "#f5a623",
     "#a175ff",
     "#31c2c9",
     "#e05f9e",
     "#8c9199"
    ],
    "legendDisplay": "right",
    "yAxisTitleText": "Events / hour",
    "xAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "A cliff on one series is a forwarder or a logging setting, not a quiet network."
  },
  "viz_stale": {
   "type": "splunk.table",
   "title": "Hosts that are delayed or stale",
   "dataSources": {
    "primary": "ds_stale"
   },
   "options": {
    "count": 12,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true,
    "columnFormat": {
     "status": {
      "rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(statusBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "stateBgConfig": [
     {
      "match": "enabled",
      "value": "#14301f"
     },
     {
      "match": "disabled",
      "value": "#4a1015"
     }
    ],
    "statusBgConfig": [
     {
      "match": "healthy",
      "value": "#14301f"
     },
     {
      "match": "delayed",
      "value": "#3a2c17"
     },
     {
      "match": "stale",
      "value": "#4a1015"
     }
    ]
   },
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.host.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_coverage": {
   "type": "splunk.table",
   "title": "Full collection inventory",
   "dataSources": {
    "primary": "ds_coverage"
   },
   "options": {
    "count": 15,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true,
    "columnFormat": {
     "status": {
      "rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(statusBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "stateBgConfig": [
     {
      "match": "enabled",
      "value": "#14301f"
     },
     {
      "match": "disabled",
      "value": "#4a1015"
     }
    ],
    "statusBgConfig": [
     {
      "match": "healthy",
      "value": "#14301f"
     },
     {
      "match": "delayed",
      "value": "#3a2c17"
     },
     {
      "match": "stale",
      "value": "#4a1015"
     }
    ]
   },
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.host.value$",
      "newTab": false
     }
    }
   ]
  },
  "hdr_geo": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Where the external traffic goes",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_geo": {
   "type": "splunk.map",
   "title": "External destinations by country",
   "dataSources": {
    "primary": "ds_geo"
   },
   "options": {
    "center": [
     20,
     0
    ],
    "zoom": 1,
    "layers": [
     {
      "type": "choropleth",
      "areaIds": "> primary | seriesByName('Country')",
      "areaValues": "> primary | seriesByName('count')"
     }
    ]
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Countries reached by outbound connections that left the internal ranges."
  },
  "viz_geo_table": {
   "type": "splunk.table",
   "title": "Countries by flow count",
   "dataSources": {
    "primary": "ds_geo_table"
   },
   "options": {
    "count": 15,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  },
  "hdr_chg": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Latest configuration changes",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_recent_changes": {
   "type": "splunk.table",
   "title": "",
   "dataSources": {
    "primary": "ds_recent_changes"
   },
   "options": {
    "count": 15,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  }
 },
 "dataSources": {
  "ds_host_list": {
   "type": "ds.search",
   "options": {
    "query": "| tstats count WHERE index IN `windows_firewall_index` sourcetype=\"windows:pfirewall\" BY host | fields host | sort host"
   },
   "name": "Host list"
  },
  "ds_changes": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_changes` | search host IN ($ms_host$) | fields _time _raw host source sourcetype index Computer Description EventID ModifyingApplication ModifyingUser Object RuleName changes critical result setting_name severity windows_firewall_event_id"
   },
   "name": "Configuration changes"
  },
  "ds_kpi_counts": {
   "type": "ds.search",
   "options": {
    "query": "| tstats `wfo_summariesonly` count AS events FROM `wfo_datamodel` WHERE nodename=Traffic $tk_noise$ host IN ($ms_host$) BY Traffic.action | rename Traffic.action AS action | stats sum(events) AS total, sum(eval(if(action=\"allowed\", events, 0))) AS allowed, sum(eval(if(action=\"blocked\", events, 0))) AS blocked | eval blocked_pct = if(total>0, round(blocked*100/total, 1), 0)"
   },
   "name": "KPI counts"
  },
  "ds_kpi_card": {
   "type": "ds.search",
   "options": {
    "query": "| tstats `wfo_summariesonly` dc(host) AS hosts, dc(Traffic.dest_ip) AS destinations, sum(Traffic.bytes) AS bytes FROM `wfo_datamodel` WHERE nodename=Traffic $tk_noise$ host IN ($ms_host$) | eval gb = round(bytes/1073741824, 2)"
   },
   "name": "KPI cardinality"
  },
  "ds_kpi_changes": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_changes",
    "query": "| stats count AS changes, count(eval(severity IN (\"critical\",\"high\"))) AS critical"
   },
   "name": "KPI changes"
  },
  "ds_timechart": {
   "type": "ds.search",
   "options": {
    "query": "| tstats `wfo_summariesonly` count FROM `wfo_datamodel` WHERE nodename=Traffic $tk_noise$ host IN ($ms_host$) BY _time, Traffic.action span=10m | rename Traffic.action AS action | timechart span=10m sum(count) BY action"
   },
   "name": "Traffic over time"
  },
  "ds_direction": {
   "type": "ds.search",
   "options": {
    "query": "| tstats `wfo_summariesonly` count FROM `wfo_datamodel` WHERE nodename=Traffic $tk_noise$ host IN ($ms_host$) BY Traffic.direction, Traffic.action | rename Traffic.* AS * | eval flow = direction.\" / \".action | stats sum(count) AS count BY flow | sort - count"
   },
   "name": "Flow mix"
  },
  "ds_top_blocked": {
   "type": "ds.search",
   "options": {
    "query": "| tstats `wfo_summariesonly` count FROM `wfo_datamodel` WHERE nodename=Traffic $tk_noise$ host IN ($ms_host$) Traffic.action=blocked BY Traffic.dest_port, Traffic.dest_service | rename Traffic.* AS * | eval service = if(isnull(dest_service) OR dest_service=\"\", \"port \".dest_port, dest_service.\" (\".dest_port.\")\") | stats sum(count) AS count BY service | sort - count | head 10"
   },
   "name": "Top blocked services"
  },
  "ds_top_talkers": {
   "type": "ds.search",
   "options": {
    "query": "| tstats `wfo_summariesonly` count AS connections FROM `wfo_datamodel` WHERE nodename=Traffic $tk_noise$ host IN ($ms_host$) BY host | sort - connections | head 10"
   },
   "name": "Top talkers"
  },
  "ds_trellis_hosts": {
   "type": "ds.search",
   "options": {
    "query": "| tstats `wfo_summariesonly` count AS events FROM `wfo_datamodel` WHERE nodename=Traffic $tk_noise$ host IN ($ms_host$) BY host, Traffic.action | rename Traffic.* AS * | eval blocked = if(action=\"blocked\", events, 0) | stats sum(events) AS events, sum(blocked) AS blocked BY host | eval blocked_pct = round(blocked*100/events, 1) | sort - events | head 12 | fields host blocked_pct"
   },
   "name": "Blocked ratio per host"
  },
  "ds_geo": {
   "type": "ds.search",
   "options": {
    "query": "| tstats `wfo_summariesonly` count FROM `wfo_datamodel` WHERE nodename=Traffic $tk_noise$ host IN ($ms_host$) Traffic.dest_scope=external BY Traffic.dest_ip | rename Traffic.dest_ip AS dest_ip | iplocation dest_ip | search Country=* | stats sum(count) AS count BY Country | geom geo_countries featureIdField=\"Country\""
   },
   "name": "External destinations"
  },
  "ds_geo_table": {
   "type": "ds.search",
   "options": {
    "query": "| tstats `wfo_summariesonly` count FROM `wfo_datamodel` WHERE nodename=Traffic $tk_noise$ host IN ($ms_host$) Traffic.dest_scope=external BY Traffic.dest_ip, Traffic.action | rename Traffic.* AS * | iplocation dest_ip | search Country=* | stats sum(count) AS flows, dc(dest_ip) AS addresses BY Country, action | sort - flows | head 30"
   },
   "name": "External destinations detail"
  },
  "ds_fw_state": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_changes` EventID IN (2003,2082,2083) SettingType=1 | search host IN ($ms_host$) | eval firewall_state = if(SettingValue=\"01000000\", \"enabled\", \"disabled\") | stats latest(_time) AS last_change, latest(firewall_state) AS state, latest(Profiles) AS profile BY Computer | eval last_change = strftime(last_change, \"%F %T\") | sort state, Computer"
   },
   "name": "Firewall state"
  },
  "ds_recent_changes": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_changes",
    "query": "| search NOT EventID IN (2010,2011,2012) | lookup windows_firewall_event_id EventID OUTPUT Description | eval Object = coalesce(RuleName, setting_name, \"-\") | table _time Computer result Object ModifyingUser ModifyingApplication severity | sort - _time | head 20"
   },
   "name": "Recent changes"
  },
  "ds_coverage": {
   "type": "ds.search",
   "options": {
    "query": "| tstats count AS events, latest(_time) AS last_seen WHERE index IN `windows_firewall_index` sourcetype=\"windows:pfirewall\" BY host, index | eval minutes_since = round((now()-last_seen)/60, 1), status = case(minutes_since < 60, \"healthy\", minutes_since < 1440, \"delayed\", true(), \"stale\"), last_seen = strftime(last_seen, \"%F %T\") | sort status, - minutes_since"
   },
   "name": "Collection health"
  },
  "ds_coverage_kpi": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_coverage",
    "query": "| stats count AS hosts, count(eval(status=\"healthy\")) AS healthy, count(eval(status=\"delayed\")) AS delayed, count(eval(status=\"stale\")) AS stale, sum(events) AS events | eval healthy_pct = if(hosts>0, round(healthy*100/hosts, 1), 0)"
   },
   "name": "Collection KPI"
  },
  "ds_stale": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_coverage",
    "query": "| where status!=\"healthy\" | head 25"
   },
   "name": "Hosts gone quiet"
  },
  "ds_volume_host": {
   "type": "ds.search",
   "options": {
    "query": "| tstats count AS events WHERE index IN `windows_firewall_index` sourcetype=\"windows:pfirewall\" BY host, _time span=1h | timechart span=1h sum(events) BY host limit=10 useother=t"
   },
   "name": "Volume per host"
  }
 },
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-24h@h,now"
   }
  },
  "input_host": {
   "type": "input.multiselect",
   "title": "Host",
   "dataSources": {
    "primary": "ds_host_list"
   },
   "options": {
    "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
    "token": "ms_host",
    "defaultValue": [
     "*"
    ],
    "valuePrefix": "\"",
    "valueSuffix": "\"",
    "delimiter": ","
   },
   "context": {
    "formattedConfig": {
     "number": {
      "prefix": ""
     }
    },
    "formattedStatics": ">statics | formatByType(formattedConfig)",
    "statics": [
     {
      "label": "All",
      "value": "*"
     }
    ],
    "label": ">primary | seriesByName(\"host\") | renameSeries(\"label\") | formatByType(formattedConfig)",
    "value": ">primary | seriesByName(\"host\") | renameSeries(\"value\") | formatByType(formattedConfig)"
   }
  },
  "input_noise": {
   "type": "input.dropdown",
   "title": "Structural noise",
   "options": {
    "token": "tk_noise",
    "defaultValue": "Traffic.is_noise=0",
    "items": [
     {
      "label": "Hide broadcast / multicast / loopback",
      "value": "Traffic.is_noise=0"
     },
     {
      "label": "Show everything",
      "value": ""
     }
    ]
   }
  }
 },
